INSERT INTO Dim_ThoiGian (Date_Key, FullDate, Nam, Quy, Thang, Tuan, Ngay, TenThu, LaaNgayLe, LaaNgayCuoiThang)
SELECT
    TO_CHAR(datum, 'YYYYMMDD')::INT AS Date_Key,
    datum AS FullDate,
    EXTRACT(YEAR FROM datum) AS Nam,
    EXTRACT(QUARTER FROM datum) AS Quy,
    EXTRACT(MONTH FROM datum) AS Thang,
    EXTRACT(WEEK FROM datum) AS Tuan,
    EXTRACT(DAY FROM datum) AS Ngay,
    CASE EXTRACT(ISODOW FROM datum)
        WHEN 1 THEN 'Thứ Hai' 
        WHEN 2 THEN 'Thứ Ba' 
        WHEN 3 THEN 'Thứ Tư'
        WHEN 4 THEN 'Thứ Năm' 
        WHEN 5 THEN 'Thứ Sáu' 
        WHEN 6 THEN 'Thứ Bảy'
        WHEN 7 THEN 'Chủ Nhật'
    END AS TenThu,
    FALSE AS LaaNgayLe, -- Các ngày lễ tết sẽ được dùng lệnh UPDATE riêng sau (ví dụ update 30/4, 1/5)
    (datum = (DATE_TRUNC('month', datum) + INTERVAL '1 month - 1 day')::DATE) AS LaaNgayCuoiThang
FROM 
    (SELECT generate_series('2020-01-01'::DATE, '2030-12-31'::DATE, '1 day'::INTERVAL)::DATE AS datum) dt;

